#include <stdio.h>
#include <string.h>
struct book { char title[24]; char author[24]; float price; };
int read_line(char *text, int capacity);
int main(void) {
    struct book volume;
    if (!read_line(volume.title, 24) || !read_line(volume.author, 24)) return 1;
    if (scanf("%f", &volume.price) != 1) return 1;
    printf("%s / %s / %.2f\n", volume.title, volume.author, volume.price);
    printf("[%s] %.2f\n", volume.title, volume.price);
    return 0;
}
int read_line(char *text, int capacity) {
    if (fgets(text, capacity, stdin) == NULL) return 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n' || ch == EOF) return 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return 0;
}

