#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
struct scores { size_t count; double average; double values[]; };
struct scores *make_scores(size_t count, double first);
int main(void) {
    struct scores *a = make_scores(2, 10.5);
    if (a == NULL) return 1;
    struct scores *b = make_scores(4, 20.0);
    if (b == NULL) { free(a); return 1; }
    int failed = printf("%zu %.2f | %zu %.2f\n", a->count, a->average, b->count, b->average) < 0;
    free(b);
    free(a);
    return failed;
}
struct scores *make_scores(size_t count, double first) {
    if (count == 0 || count > (SIZE_MAX - sizeof(struct scores)) / sizeof(double)) return NULL;
    struct scores *result = malloc(sizeof(struct scores) + count * sizeof(double));
    if (result == NULL) return NULL;
    result->count = count;
    double total = 0.0;
    for (size_t i = 0; i < count; i++) {
        result->values[i] = first - 0.5 * (double)i;
        total += result->values[i];
    }
    result->average = total / (double)count;
    return result;
}

