#include <stdio.h>
#include <string.h>
#include <math.h>
struct book { char title[32]; char author[32]; double price; };
int read_line(char *text, int capacity);
int main(void) {
    struct book shelf[10];
    FILE *file = fopen("reading_books_v1.bin", "r+b");
    if (file == NULL) file = fopen("reading_books_v1.bin", "w+bx");
    if (file == NULL) return 1;
    int count = 0, failed = 0;
    while (count < 10) {
        size_t bytes = fread(&shelf[count], 1, sizeof shelf[count], file);
        if (bytes == 0 && feof(file)) break;
        if (bytes != sizeof shelf[count] || ferror(file)) { failed = 1; break; }
        if (memchr(shelf[count].title, '\0', 32) == NULL ||
            memchr(shelf[count].author, '\0', 32) == NULL || !isfinite(shelf[count].price)) {
            failed = 1; break;
        }
        count++;
    }
    if (!failed && count == 10) {
        int extra = getc(file);
        if (extra != EOF || ferror(file)) failed = 1;
    }
    int old_count = count;
    while (!failed && count < 10) {
        puts("TITLE (empty to end):");
        int status = read_line(shelf[count].title, 32);
        if (status == 0 || (status == 1 && shelf[count].title[0] == '\0')) break;
        if (status < 0 || read_line(shelf[count].author, 32) != 1 ||
            scanf("%lf", &shelf[count].price) != 1 || !isfinite(shelf[count].price)) {
            failed = 1; break;
        }
        int ch = getchar();
        while (ch != '\n' && ch != EOF) ch = getchar();
        if (ferror(stdin)) { failed = 1; break; }
        count++;
    }
    if (!failed && fseek(file, 0L, SEEK_END) != 0) failed = 1;
    for (int i = old_count; !failed && i < count; i++)
        if (fwrite(&shelf[i], sizeof shelf[i], 1, file) != 1) failed = 1;
    if (fclose(file) != 0) failed = 1;
    if (!failed) for (int i = 0; i < count; i++)
        if (printf("%s / %s / %.2f\n", shelf[i].title, shelf[i].author, shelf[i].price) < 0) failed = 1;
    return failed;
}
int read_line(char *text, int capacity) {
    if (fgets(text, capacity, stdin) == NULL) return ferror(stdin) ? -1 : 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -1 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return -1;
}

#include <stdio.h>
#include <string.h>
enum color { amber, teal, violet };
int main(void) {
    char name[16];
    while (fgets(name, 16, stdin) != NULL) {
        char *end = strchr(name, '\n');
        if (end != NULL) *end = '\0';
        if (name[0] == '\0') break;
        int found = 1;
        enum color selected = amber;
        if (strcmp(name, "amber") == 0) selected = amber;
        else if (strcmp(name, "teal") == 0) selected = teal;
        else if (strcmp(name, "violet") == 0) selected = violet;
        else found = 0;
        if (!found) puts("UNKNOWN");
        else switch (selected) {
            case amber: puts("warm"); break;
            case teal: puts("cool"); break;
            case violet: puts("mixed"); break;
        }
    }
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>
void upper(char *text);
void lower(char *text);
void transpose(char *text);
void original(char *text);
int read_line(char *text, int capacity);
int read_choice(void);
int main(void) {
    char source[64], copy[64];
    int status;
    while ((status = read_line(source, 64)) == 1 && source[0] != '\0') {
        while (1) {
            int choice = read_choice();
            if (choice == EOF || choice == 'n') break;
            void (*action)(char *) = NULL;
            switch (choice) {
                case 'u': action = upper; break;
                case 'l': action = lower; break;
                case 't': action = transpose; break;
                case 'o': action = original; break;
            }
            if (action == NULL) { puts("INVALID"); continue; }
            strcpy(copy, source);
            action(copy);
            puts(copy);
        }
        if (feof(stdin) || ferror(stdin)) break;
    }
    return status < 0 || ferror(stdin) ? 1 : 0;
}
void upper(char *text) {
    for (; *text != '\0'; text++) *text = (char)toupper((unsigned char)*text);
}
void lower(char *text) {
    for (; *text != '\0'; text++) *text = (char)tolower((unsigned char)*text);
}
void transpose(char *text) {
    for (; *text != '\0'; text++) {
        unsigned char ch = (unsigned char)*text;
        if (islower(ch)) *text = (char)toupper(ch);
        else if (isupper(ch)) *text = (char)tolower(ch);
    }
}
void original(char *text) { (void)text; }
int read_choice(void) {
    int ch = getchar();
    if (ch == EOF) return EOF;
    int tail;
    if (ch != '\n') while ((tail = getchar()) != '\n' && tail != EOF) {}
    return ch;
}
int read_line(char *text, int capacity) {
    if (fgets(text, capacity, stdin) == NULL) return ferror(stdin) ? -1 : 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -1 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return -1;
}

